#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    long long m;

    while (scanf("%d%lld", &n, &m) == 2) {
        vector<long long> a(n);
        for (long long &x : a) scanf("%lld", &x);

        sort(a.begin(), a.end());

        long long ans = 0;
        long long maxx = a[n - 1];
        int t = n - 1;
        const long long limit = 2LL * m;

        while (maxx > limit) {
            long long next = maxx / 2 + maxx % 2;
            int pos = lower_bound(a.begin(), a.begin() + t, next) - a.begin();

            if (pos == t) {
                if (next == maxx) break;
                ++ans;
                maxx = next;
            } else {
                t = pos;
                maxx = a[pos];
            }
        }

        printf("%lld\n", ans);
    }

    return 0;
}

